// All profiles, costs, deductions and employment rules are game assumptions.
// The user's 15/25/35/20/5 weights are NOT Korean population shares.
export const HOUSEHOLD_PROFILES=[
 {id:'poor',name:'빈곤 가정 · 게임 설정',weight:15,cash:[500000,3000000],debt:[0,3000000],debtChance:.45,wage:.55,living:.7,home:0},
 {id:'low',name:'서민 가정 · 게임 설정',weight:25,cash:[5000000,20000000],debt:[0,15000000],debtChance:.65,wage:.8,living:.85,home:0},
 {id:'middle',name:'일반 중산층 · 게임 설정',weight:35,cash:[20000000,60000000],debt:[0,40000000],debtChance:.6,wage:1.1,living:1,home:0},
 {id:'upper',name:'중상층 · 게임 설정',weight:20,cash:[60000000,200000000],debt:[0,80000000],debtChance:.55,wage:1.6,living:1.3,home:1},
 {id:'wealthy',name:'부유층 · 게임 설정',weight:5,cash:[200000000,600000000],debt:[0,100000000],debtChance:.3,wage:2.5,living:1.8,home:2}
];
const mi=m=>Number(m.slice(0,4))*12+Number(m.slice(5))-1;
export const householdAge=s=>s.startAge+Math.floor((mi(s.month)-mi(s.start))/12);
const monthAt=i=>`${Math.floor(i/12)}-${String(i%12+1).padStart(2,'0')}`;
export function pickHousehold(value){if(!Number.isFinite(value)||value<0||value>=1)throw Error('무작위 값은 0~1 미만이어야 합니다.');let edge=0;return HOUSEHOLD_PROFILES.find(p=>value*100<(edge+=p.weight));}
export function initializeHousehold(s,mode='manual',random=Math.random){if(!['manual','random'].includes(mode))throw Error('가정환경 설정을 확인해 주세요.');const p=mode==='random'?pickHousehold(random()):null;const draw=range=>{const v=random();if(!Number.isFinite(v)||v<0||v>=1)throw Error('무작위 값이 올바르지 않습니다.');return Math.round(range[0]+v*(range[1]-range[0]));};
 s.household={version:1,mode,profile:p?.id||null,wageFactor:p?.wage||1,privateInsurance:false,retired:householdAge(s)>=60,jobReadyAt:null,initialWealth:0,initialDebt:0,debtBalance:0,debtInterest:0};
 if(p){const cash=draw(p.cash),debt=random()<p.debtChance?draw(p.debt):0;if(s.startMode==='birth'){s.cash=cash;s.initial=cash;s.gross=cash;}else s.cash+=cash;s.home=Math.round(s.houseBase*p.home);s.living=Math.round(s.living*p.living);s.debt+=debt;Object.assign(s.household,{initialWealth:cash+s.home-debt,initialDebt:debt,debtBalance:debt});}
 if(s.household.retired)s.job=false;
 s.log.push({id:s.log.length+1,month:s.month,type:'start',title:p?'무작위 가정환경 · '+p.name:'월 가계 모형 시작',text:'15/25/35/20/5 배정은 게임 설정이며 실제 계층 비율이 아닙니다. 추가 가정 순자산 '+s.household.initialWealth.toLocaleString('ko-KR')+'원, 기존 부채 '+s.household.initialDebt.toLocaleString('ko-KR')+'원. 보험·공제·구직·퇴직 조건과 자산 범위는 게임 가정입니다.'});
}
export function grossSalary(s,base){const h=s.household;if(!h)return base;if(h.retired&&!s.job)return 0;return Math.round(base*h.wageFactor*(h.retired?.35:1));}
export function payroll(s,gross){if(!s.household)return {gross,deduction:0,net:gross,social:0,tax:0};const social=Math.round(gross*.08),tax=Math.round(gross*(gross>7000000?.18:gross>4000000?.12:gross>2000000?.07:.03));return {gross,social,tax,deduction:social+tax,net:gross-social-tax};}
export function householdCosts(s){if(!s.household)return {medical:0,privateInsurance:0,carInsurance:0,homeInsurance:0,total:0};const medical=Math.round((householdAge(s)>=65?120000:50000)*s.cpi),privateInsurance=s.household.privateInsurance?Math.round(80000*s.cpi):0,carInsurance=s.car?Math.round(60000*s.cpi):0,homeInsurance=s.home?Math.round(15000*s.cpi):0;return {medical,privateInsurance,carInsurance,homeInsurance,total:medical+privateInsurance+carInsurance+homeInsurance};}
export function householdDue(s){const h=s.household;if(!h)return 0;return Math.min(h.debtBalance,Math.ceil(h.initialDebt/120))+Math.round(h.debtBalance*.05/12)+h.debtInterest;}
export function stepHouseholdDebt(s){const h=s.household,flow={interestIncurred:0,interestPaid:0,principalPaid:0,due:householdDue(s)};if(!h||h.debtBalance+h.debtInterest<=0)return flow;const interest=Math.round(h.debtBalance*.05/12),owed=h.debtInterest+interest;const paid=Math.min(Math.max(0,s.cash),owed);s.cash-=paid;s.debt+=interest-paid;h.debtInterest=owed-paid;const principal=Math.min(Math.max(0,s.cash),h.debtBalance,Math.ceil(h.initialDebt/120));s.cash-=principal;s.debt-=principal;h.debtBalance-=principal;Object.assign(flow,{interestIncurred:interest,interestPaid:paid,principalPaid:principal});return flow;}
export function jobTransition(s,working){const h=s.household;if(!h){s.job=working;return;}if(working&&h.jobReadyAt!==null&&mi(s.month)<h.jobReadyAt)throw Error('구직 준비 기간이 끝난 뒤 재취업할 수 있습니다.');s.job=working;if(!working)h.jobReadyAt=mi(s.month)+3;else h.jobReadyAt=null;}
export function stepRetirement(s){const h=s.household;if(!h||h.retired||s.startMode==='birth'&&householdAge(s)<19||householdAge(s)<60)return false;h.retired=true;jobTransition(s,false);s.log.push({id:s.log.length+1,month:s.month,type:'result',title:'60세, 퇴직과 다음 생활',text:'정상 급여를 중단했습니다. 구직 준비 3개월 후 다시 일하면 급여 모형의 35%를 사용합니다. 실제 법정 정년·재취업률·연금 수급 예측이 아닌 게임 가정이며 자동 연금은 지급하지 않습니다.'});return true;}
export function setInsurance(s,on){if(!s.household||s.ended||s.pending||householdAge(s)<19||typeof on!=='boolean')throw Error('보험 설정을 확인해 주세요.');if(s.household.insuranceMonth===s.month)throw Error('보험 선택은 월 1회만 변경할 수 있습니다.');s.household.privateInsurance=on;s.household.insuranceMonth=s.month;s.log.push({id:s.log.length+1,month:s.month,type:'choice',title:on?'민간보험 모형 가입':'민간보험 모형 해지',text:'다음 월부터 기본 80,000원 × 물가 배율의 보험료를 적용합니다. 실제 보험 상품이 아닙니다. 가상 입원 사건의 모형 비용 80%, 연간 물가 조정 1,000만원 한도로 차감합니다. 실제 약관·보험금 지급 기준이 아니며 피해 확률은 변하지 않습니다.'});}
export function validHousehold(s){const h=s.household;if(h===undefined)return true;if(!h||h.version!==1||!['manual','random'].includes(h.mode)||!Number.isFinite(h.wageFactor)||h.wageFactor<=0||h.wageFactor>3||typeof h.retired!=='boolean'||typeof h.privateInsurance!=='boolean'||h.mode==='random'&&!HOUSEHOLD_PROFILES.some(p=>p.id===h.profile)||h.mode==='manual'&&h.profile!==null)return false;if(!['initialWealth','initialDebt','debtBalance','debtInterest'].every(k=>Number.isSafeInteger(h[k])&&Math.abs(h[k])<1e15)||h.initialDebt<0||h.debtBalance<0||h.debtInterest<0||h.debtBalance>h.initialDebt||h.debtBalance+h.debtInterest>s.debt)return false;if(h.claimPaid!==undefined&&(!Number.isSafeInteger(h.claimPaid)||h.claimPaid<0||h.claimPaid>1e15||typeof h.claimYear!=='string'||!/^\d{4}$/.test(h.claimYear)||h.claimYear>s.month.slice(0,4)))return false;return (h.jobReadyAt===null||Number.isInteger(h.jobReadyAt)&&h.jobReadyAt>=mi(s.start)&&h.jobReadyAt<=mi(s.endAt||'2026-10')+3)&&(h.insuranceMonth===undefined||typeof h.insuranceMonth==='string'&&/^\d{4}-(0[1-9]|1[0-2])$/.test(h.insuranceMonth)&&h.insuranceMonth>=s.start&&h.insuranceMonth<=s.month);}
export function insuranceBenefit(s,gross){const h=s.household;if(!h?.privateInsurance)return 0;const used=h.claimYear===s.month.slice(0,4)?h.claimPaid||0:0;return Math.max(0,Math.min(Math.round(gross*.8),Math.round(10000000*s.cpi)-used));}
export function recordInsuranceBenefit(s,gross){const benefit=insuranceBenefit(s,gross),h=s.household;if(benefit>0){if(h.claimYear!==s.month.slice(0,4)){h.claimYear=s.month.slice(0,4);h.claimPaid=0;}h.claimPaid+=benefit;}return benefit;}
